messages.content:
[
 {
  "code": "UK-A01",
  "title": "Helpdesk Coordinator",
  "desc": "Logs reactive calls from client sites and assigns them to engineers by roster; chases completion."
 },
 {
  "code": "UK-A02",
  "title": "Site Administrator",
  "desc": "Keeps permits"
 },
 {
  "code": "UK-A03",
  "title": "Mobile Operative",
  "desc": "Cleaning and minor maintenance tasks under a supervisor; no trade qualification."
 },
 {
  "code": "UK-A04",
  "title": "Apprentice Engineer",
  "desc": "Trainee on a four-year building-services apprenticeship; always works under supervision."
 },
 {
  "code": "UK-B01",
  "title": "Engineer (Multi-skilled)",
  "desc": "Planned and reactive maintenance on building services; holds an electrical or mechanical trade qualification; works alone across client sites."
 },
 {
  "code": "UK-B02",
  "title": "Engineer (HVAC)",
  "desc": "Services and repairs air-conditioning plant; holds a refrigerant-handling certificate; works alone."
 },
 {
  "code": "UK-B03",
  "title": "Electrical Engineer",
  "desc": "Fault-finding and testing on low-voltage installations; trade-qualified electrician; works alone on site."
 },
 {
  "code": "UK-B04",
  "title": "Security Officer",
  "desc": "Static and patrol security at rail stations; holds a security license; works to post instructions."
 },
 {
  "code": "UK-B05",
  "title": "Planner",
  "desc": "Schedules planned maintenance for one contract in the maintenance system and reports completion against the plan."
 },
 {
  "code": "UK-B06",
  "title": "Engineer (Fire Systems)",
  "desc": "Maintains fire alarm and suppression systems; trade certification; works alone."
 },
 {
  "code": "UK-B07",
  "title": "Payroll Officer",
  "desc": "Prepares UK payroll inputs and checks; professional payroll qualification; work reviewed by the payroll manager."
 },
 {
  "code": "UK-C01",
  "title": "Senior Engineer",
  "desc": "Diagnoses complex plant faults and leads two to four engineers on a large site; no budget or hiring authority."
 },
 {
  "code": "UK-C02",
  "title": "Lead Electrician",
  "desc": "Leads electrical works on rail station contracts with up to six people on site."
 },
 {
  "code": "UK-C03",
  "title": "Health and Safety Advisor",
  "desc": "Holds a professional safety diploma; audits sites and investigates incidents independently."
 },
 {
  "code": "UK-C04",
  "title": "Bid Writer",
  "desc": "Writes sections of public-sector tender responses; work reviewed by the bid manager."
 },
 {
  "code": "UK-C05",
  "title": "Quantity Surveyor",
  "desc": "Degree-qualified; values variations and prices changes on own contracts."
 },
 {
  "code": "UK-D01",
  "title": "Supervisor",
  "desc": "Runs several engineering crews on a contract; signs safety permits"
 },
 {
  "code": "UK-D02",
  "title": "Shift Supervisor (Security)",
  "desc": "Leads a security shift of 10 to 15 officers; sets the roster; handles first-stage discipline."
 },
 {
  "code": "UK-D03",
  "title": "Contract Engineer",
  "desc": "Degree-qualified building-services engineer and technical lead for one contract; signs off designs; no direct reports."
 },
 {
  "code": "UK-D04",
  "title": "HR Advisor",
  "desc": "Professionally qualified; advises managers on employee-relations cases independently."
 },
 {
  "code": "UK-E01",
  "title": "Contract Manager",
  "desc": "Runs a facilities contract with its own budget line and 30 to 60 staff."
 },
 {
  "code": "UK-E02",
  "title": "Area Manager",
  "desc": "Runs several contracts across a region through their contract managers."
 },
 {
  "code": "UK-E03",
  "title": "Finance Business Partner",
  "desc": "Qualified accountant; partners a region's contract managers; leads two analysts."
 },
 {
  "code": "UK-F01",
  "title": "Regional Director",
  "desc": "Leads Hartwell UK's operations in one region; member of the UK leadership team."
 },
 {
  "code": "DE-EG04",
  "title": "Facility-Mitarbeiter",
  "desc": "Cleaning"
 },
 {
  "code": "DE-EG05",
  "title": "Monteur (Betriebstechnik)",
  "desc": "Installs and maintains industrial building services; completed trade apprenticeship; works alone."
 },
 {
  "code": "DE-EG06",
  "title": "Kundendiensttechniker",
  "desc": "Service technician on call-outs; trade qualification; works alone."
 },
 {
  "code": "DE-EG07",
  "title": "Elektroniker (Schichtleitung)",
  "desc": "Electrician who leads a shift crew of up to five; no hiring authority."
 },
 {
  "code": "DE-EG08",
  "title": "Sachbearbeiter Personal",
  "desc": "HR administrator; prepares contracts and payroll inputs by procedure."
 },
 {
  "code": "DE-EG09",
  "title": "Meister (Haustechnik)",
  "desc": "Master craftsman; plans work for several crews"
 },
 {
  "code": "DE-EG10",
  "title": "Ingenieur Versorgungstechnik",
  "desc": "Degree-qualified building-services engineer; designs and signs off modifications; works independently."
 },
 {
  "code": "DE-AT01",
  "title": "Objektleiter",
  "desc": "Site manager for one industrial client; budget line; 20 to 40 staff."
 },
 {
  "code": "NL-FG04",
  "title": "Medewerker Facilitair",
  "desc": "Facilities assistant; set tasks under supervision."
 },
 {
  "code": "NL-FG05",
  "title": "Administratief Medewerker HR",
  "desc": "HR administration by procedure."
 },
 {
  "code": "NL-FG06",
  "title": "Monteur Werktuigbouw",
  "desc": "Mechanical technician on port facilities; trade qualification; works alone."
 },
 {
  "code": "NL-FG07",
  "title": "Planner Onderhoud",
  "desc": "Maintenance planner; schedules planned work in the maintenance system."
 },
 {
  "code": "NL-FG08",
  "title": "Technisch Specialist",
  "desc": "Diagnoses complex installations and leads up to four colleagues on site; no budget."
 },
 {
  "code": "NL-FG09",
  "title": "Ploegleider",
  "desc": "Crew leader who plans work for several crews"
 },
 {
  "code": "NL-FG10",
  "title": "Projectleider",
  "desc": "Runs projects with a budget and a small team."
 },
 {
  "code": "NL-FG11",
  "title": "Vestigingsmanager",
  "desc": "Site manager with a budget and about 40 staff."
 }
]
